-- DIRECT Run Batch, activity 'Open Batch' (repository database).
-- Opens the Batch Instance, the Module Instances of the Batch and, recursively, its active child Batches with
-- omd.CreateBatchModuleInstances (the Modules of a Batch first, then its child Batches in sequence, as omd.RunBatch does).
-- Returns one row: BATCH_INSTANCE_ID, INTERNAL_PROCESSING_STATUS_CODE, BATCH_CODE, MODULE_COUNT, BATCH_INSTANCE_COUNT,
--   MODULES (JSON array with the 'Proceed' rows of omd.CreateBatchModuleInstances, in run order) and
--   BATCH_INSTANCES (JSON array with the Batch Instances that were opened: id, code, parent, level, status, module count).
-- Parameters: @BatchCode, @ParentBatchInstanceId (string, '0' when none), @ExecutionContext,
--             @ModuleInstanceIdColumnName, @DefaultStartValue, @ConsistencyModuleTypeList, @SourceTimestampColumn.
SET NOCOUNT ON;

DECLARE @BatchInstanceId BIGINT;
DECLARE @InternalProcessingStatusCode NVARCHAR(100);
DECLARE @SuccessIndicator CHAR(1) = 'N';
DECLARE @MessageLog NVARCHAR(MAX);
DECLARE @ErrorMessage NVARCHAR(2048);
DECLARE @ParentId BIGINT = COALESCE(TRY_CONVERT(BIGINT, NULLIF(TRIM(@ParentBatchInstanceId), N'')), 0);
DECLARE @ConsistencyTypes NVARCHAR(4000) = NULLIF(TRIM(@ConsistencyModuleTypeList), N'');

DECLARE @Modules NVARCHAR(MAX);
DECLARE @BatchInstances NVARCHAR(MAX);

-- The rows come back as JSON (no INSERT ... EXEC, which would wrap the call in a transaction that a failed evaluation dooms).
EXEC [omd].[CreateBatchModuleInstances]
   @BatchCode                    = @BatchCode
  ,@ParentBatchInstanceId        = @ParentId
  ,@ExecutionContext             = @ExecutionContext
  ,@ModuleInstanceIdColumnName   = @ModuleInstanceIdColumnName
  ,@DefaultStartValue            = @DefaultStartValue
  ,@ConsistencyModuleTypeList    = @ConsistencyTypes
  ,@SourceTimestampColumn        = @SourceTimestampColumn
  ,@ReturnResultSet              = 'N'
  ,@IncludeChildBatches          = 'Y'
  ,@ResultJson                   = @Modules OUTPUT
  ,@BatchInstancesJson           = @BatchInstances OUTPUT
  ,@BatchInstanceId              = @BatchInstanceId OUTPUT
  ,@InternalProcessingStatusCode = @InternalProcessingStatusCode OUTPUT
  ,@SuccessIndicator             = @SuccessIndicator OUTPUT
  ,@MessageLog                   = @MessageLog OUTPUT;

IF @SuccessIndicator <> 'Y'
BEGIN
  IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  SET @ErrorMessage = LEFT(N'DIRECT could not open Batch ''' + COALESCE(@BatchCode, N'') + N''': ' + COALESCE(@MessageLog, N''), 2048);
  THROW 50000, @ErrorMessage, 1;
END;

-- Only the Modules that proceed are handed to the orchestrator, in run order (RUN_ORDER is the position in that order)
SET @Modules = COALESCE(
(
  SELECT
     ROW_NUMBER() OVER (ORDER BY TRY_CONVERT(INT, arr.[key])) AS RUN_ORDER
    ,r.BATCH_INSTANCE_ID, r.BATCH_CODE, r.MODULE_INSTANCE_ID, r.MODULE_ID, r.MODULE_CODE, r.MODULE_TYPE, r.AREA_CODE, r.[SEQUENCE]
    ,r.EXECUTABLE, r.DATA_OBJECT_SOURCE, r.DATA_OBJECT_TARGET, r.PREVIOUS_END_VALUE, r.INTERNAL_PROCESSING_STATUS_CODE, r.ROLLBACK_STATEMENT, r.CONSISTENCY_DATETIME
  FROM OPENJSON(@Modules) arr
  CROSS APPLY OPENJSON(arr.[value])
  WITH
  (
     BATCH_INSTANCE_ID BIGINT, BATCH_CODE NVARCHAR(500), MODULE_INSTANCE_ID BIGINT, MODULE_ID INT, MODULE_CODE NVARCHAR(500), MODULE_TYPE NVARCHAR(100)
    ,AREA_CODE NVARCHAR(100), [SEQUENCE] INT, EXECUTABLE NVARCHAR(MAX), DATA_OBJECT_SOURCE NVARCHAR(1000), DATA_OBJECT_TARGET NVARCHAR(1000)
    ,PREVIOUS_END_VALUE NVARCHAR(100), INTERNAL_PROCESSING_STATUS_CODE NVARCHAR(100), ROLLBACK_STATEMENT NVARCHAR(MAX), CONSISTENCY_DATETIME NVARCHAR(27)
  ) r
  WHERE r.INTERNAL_PROCESSING_STATUS_CODE = N'Proceed'
  ORDER BY TRY_CONVERT(INT, arr.[key])
  FOR JSON PATH
), N'[]');

SELECT
   @BatchInstanceId AS BATCH_INSTANCE_ID
  ,@InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE
  ,@BatchCode AS BATCH_CODE
  ,(SELECT COUNT(*) FROM OPENJSON(@Modules)) AS MODULE_COUNT
  ,(SELECT COUNT(*) FROM OPENJSON(COALESCE(@BatchInstances, N'[]'))) AS BATCH_INSTANCE_COUNT
  ,@Modules AS MODULES
  ,COALESCE(@BatchInstances, N'[]') AS BATCH_INSTANCES;

-- DIRECT Run Batch / Run Module, activity 'Run Modules' (target engine, Fabric Warehouse).
-- Runs the Modules in @Modules (JSON array with the rows of omd.CreateBatchModuleInstances) in array order, which is the
-- run order of the Batch and its child Batches.
-- Per Module: rollback statement (if any), load window end from the source data object, the executable through
-- sp_executesql with the parameters @ModuleInstanceId, @StartValue, @EndValue and @ConsistencyDateTime, and the
-- target row count before and after. One result row per Module, in the shape omd.EndBatchModuleInstances expects.
-- Parameters: @Modules (string, JSON), @LoadWindowAttributeName (string).
CREATE TABLE #modules
(
   [SEQ]                            INT
  ,[BATCH_CODE]                     VARCHAR(500)
  ,[MODULE_INSTANCE_ID]             BIGINT
  ,[MODULE_CODE]                    VARCHAR(500)
  ,[EXECUTABLE]                     VARCHAR(8000)
  ,[DATA_OBJECT_SOURCE]             VARCHAR(1000)
  ,[DATA_OBJECT_TARGET]             VARCHAR(1000)
  ,[PREVIOUS_END_VALUE]             VARCHAR(100)
  ,[INTERNAL_PROCESSING_STATUS_CODE] VARCHAR(100)
  ,[ROLLBACK_STATEMENT]             VARCHAR(8000)
  ,[CONSISTENCY_DATETIME]           VARCHAR(100)
);

INSERT INTO #modules
SELECT
   ROW_NUMBER() OVER (ORDER BY TRY_CONVERT(INT, arr.[key]))
  ,r.[BATCH_CODE], r.[MODULE_INSTANCE_ID], r.[MODULE_CODE], r.[EXECUTABLE], r.[DATA_OBJECT_SOURCE], r.[DATA_OBJECT_TARGET], r.[PREVIOUS_END_VALUE]
  ,r.[INTERNAL_PROCESSING_STATUS_CODE], r.[ROLLBACK_STATEMENT], r.[CONSISTENCY_DATETIME]
FROM OPENJSON(@Modules) arr
CROSS APPLY OPENJSON(arr.[value])
WITH
(
   [BATCH_CODE]                     VARCHAR(500)
  ,[MODULE_INSTANCE_ID]             BIGINT
  ,[MODULE_CODE]                    VARCHAR(500)
  ,[EXECUTABLE]                     VARCHAR(8000)
  ,[DATA_OBJECT_SOURCE]             VARCHAR(1000)
  ,[DATA_OBJECT_TARGET]             VARCHAR(1000)
  ,[PREVIOUS_END_VALUE]             VARCHAR(100)
  ,[INTERNAL_PROCESSING_STATUS_CODE] VARCHAR(100)
  ,[ROLLBACK_STATEMENT]             VARCHAR(8000)
  ,[CONSISTENCY_DATETIME]           VARCHAR(100)
) r
WHERE r.[INTERNAL_PROCESSING_STATUS_CODE] = 'Proceed';

CREATE TABLE #results
(
   [Seq]              INT
  ,[BatchCode]        VARCHAR(500)
  ,[ModuleInstanceId] BIGINT
  ,[ModuleCode]       VARCHAR(500)
  ,[EventCode]        VARCHAR(100)
  ,[StartValue]       VARCHAR(100)
  ,[EndValue]         VARCHAR(100)
  ,[RowCountInsert]   BIGINT
  ,[RowCountDeleted]  BIGINT
  ,[EventDetail]      VARCHAR(4000)
  ,[DurationMs]       INT
);

DECLARE @i INT = 0;
DECLARE @n INT = (SELECT COUNT(*) FROM #modules);
DECLARE @WindowColumn VARCHAR(128) = COALESCE(NULLIF(TRIM(@LoadWindowAttributeName), ''), 'INSCRIPTION_TIMESTAMP');
DECLARE @ParameterDefinition NVARCHAR(500) = N'@ModuleInstanceId BIGINT, @StartValue VARCHAR(100), @EndValue VARCHAR(100), @ConsistencyDateTime VARCHAR(100)';

DECLARE @ModuleInstanceId BIGINT, @BatchCode VARCHAR(500), @ModuleCode VARCHAR(500), @Executable NVARCHAR(MAX), @Source VARCHAR(1000), @Target VARCHAR(1000);
DECLARE @StartValue VARCHAR(100), @EndValue VARCHAR(100), @Rollback NVARCHAR(MAX), @ConsistencyDateTime VARCHAR(100);
DECLARE @Sql NVARCHAR(MAX), @Before BIGINT, @After BIGINT, @T0 DATETIME2(6), @Step VARCHAR(50);
DECLARE @WindowKnown BIT, @RowCountInsert BIGINT, @RowCountDeleted BIGINT;

WHILE @i < @n
BEGIN
  SET @i = @i + 1;

  SELECT
     @ModuleInstanceId = [MODULE_INSTANCE_ID], @BatchCode = [BATCH_CODE], @ModuleCode = [MODULE_CODE], @Executable = [EXECUTABLE]
    ,@Source = [DATA_OBJECT_SOURCE], @Target = [DATA_OBJECT_TARGET], @StartValue = [PREVIOUS_END_VALUE]
    ,@Rollback = [ROLLBACK_STATEMENT], @ConsistencyDateTime = [CONSISTENCY_DATETIME]
  FROM #modules
  WHERE [SEQ] = @i;

  SET @T0 = SYSDATETIME();
  SET @EndValue = NULL;
  SET @Before = NULL;
  SET @After = NULL;
  SET @Step = 'rollback';

  BEGIN TRY
    -- Rollback of earlier failed instances, decided by the Module evaluation in the repository
    IF @Rollback IS NOT NULL AND TRIM(@Rollback) <> ''
    BEGIN
      EXEC sp_executesql @Rollback;
    END;

    -- Load window end: the latest load window attribute value in the source data object.
    -- An empty source keeps the window closed at its start value, so that the recorded end does not run ahead of the data.
    -- When the source has no such attribute (for example an operational source), the current time is used.
    SET @Step = 'load window';
    SET @WindowKnown = 0;
    IF @Source IS NOT NULL AND TRIM(@Source) <> ''
    BEGIN
      BEGIN TRY
        SET @Sql = N'SELECT @e = CONVERT(VARCHAR(27), MAX(' + QUOTENAME(@WindowColumn) + N'), 121) FROM ' + @Source;
        EXEC sp_executesql @Sql, N'@e VARCHAR(27) OUTPUT', @e = @EndValue OUTPUT;
        SET @WindowKnown = 1;
      END TRY
      BEGIN CATCH
        SET @EndValue = NULL;
      END CATCH;
    END;
    IF @EndValue IS NULL SET @EndValue = CASE WHEN @WindowKnown = 1 THEN @StartValue ELSE CONVERT(VARCHAR(27), SYSDATETIME(), 121) END;

    -- Target row count before
    SET @Step = 'row count';
    IF @Target IS NOT NULL AND TRIM(@Target) <> ''
    BEGIN
      BEGIN TRY
        SET @Sql = N'SELECT @c = COUNT_BIG(*) FROM ' + @Target;
        EXEC sp_executesql @Sql, N'@c BIGINT OUTPUT', @c = @Before OUTPUT;
      END TRY
      BEGIN CATCH
        SET @Before = NULL;
      END CATCH;
    END;

    -- The executable
    SET @Step = 'executable';
    EXEC sp_executesql @Executable, @ParameterDefinition
      ,@ModuleInstanceId = @ModuleInstanceId, @StartValue = @StartValue, @EndValue = @EndValue, @ConsistencyDateTime = @ConsistencyDateTime;

    -- Target row count after
    SET @Step = 'row count';
    IF @Before IS NOT NULL
    BEGIN
      BEGIN TRY
        SET @Sql = N'SELECT @c = COUNT_BIG(*) FROM ' + @Target;
        EXEC sp_executesql @Sql, N'@c BIGINT OUTPUT', @c = @After OUTPUT;
      END TRY
      BEGIN CATCH
        SET @After = NULL;
      END CATCH;
    END;

    -- Row counts from the target counts: a target that holds fewer rows than before was reset and reloaded
    -- (for example a truncate-and-load Landing table), so its old rows count as deleted and the new rows as inserted.
    SET @RowCountInsert = CASE WHEN @After >= @Before THEN @After - @Before ELSE @After END;
    SET @RowCountDeleted = CASE WHEN @After < @Before THEN @Before ELSE 0 END;

    INSERT INTO #results VALUES (@i, @BatchCode, @ModuleInstanceId, @ModuleCode, 'Success', @StartValue, @EndValue, @RowCountInsert, @RowCountDeleted, NULL, DATEDIFF(MILLISECOND, @T0, SYSDATETIME()));
  END TRY
  BEGIN CATCH
    INSERT INTO #results VALUES (@i, @BatchCode, @ModuleInstanceId, @ModuleCode, 'Failure', @StartValue, @EndValue, NULL, NULL,
      LEFT('Error in ' + @Step + ' (' + CONVERT(VARCHAR(20), ERROR_NUMBER()) + '): ' + ERROR_MESSAGE(), 4000), DATEDIFF(MILLISECOND, @T0, SYSDATETIME()));
  END CATCH;
END;

SELECT [Seq], [BatchCode], [ModuleInstanceId], [ModuleCode], [EventCode], [StartValue], [EndValue], [RowCountInsert], [RowCountDeleted], [EventDetail], [DurationMs]
FROM #results
ORDER BY [Seq];

-- DIRECT Run Batch, activity 'Close Batch' (repository database).
-- Reports the Module results to omd.EndBatchModuleInstances, which closes the Module Instances, the child Batch Instances
-- (deepest level first) and the Batch Instance itself. A failed Module or child Batch Instance fails its Batch Instance.
-- With @RaiseError = 'Y' the activity fails (after the bookkeeping) when the Batch failed, so that the pipeline run shows the failure.
-- Parameters: @BatchInstanceId (string), @InternalProcessingStatusCode, @ModuleResults (string, JSON),
--             @BatchEventCode (string, '' for derived), @RaiseError (string, 'Y' or 'N').
SET NOCOUNT ON;

DECLARE @Id BIGINT = TRY_CONVERT(BIGINT, NULLIF(TRIM(@BatchInstanceId), N''));
DECLARE @Results NVARCHAR(MAX) = NULLIF(TRIM(@ModuleResults), N'');
DECLARE @EventCode NVARCHAR(100) = NULLIF(TRIM(@BatchEventCode), N'');
DECLARE @ReportedCount INT, @FailedCount INT, @FailedBatchCount INT, @ExecutionStatusCode NVARCHAR(100);
DECLARE @SuccessIndicator CHAR(1) = 'N';
DECLARE @MessageLog NVARCHAR(MAX);
DECLARE @ErrorMessage NVARCHAR(2048);

IF @Id IS NULL OR @InternalProcessingStatusCode <> N'Proceed'
BEGIN
  -- The Batch Instance was closed by its evaluation (Cancel or Abort); nothing to report.
  SELECT @Id AS BATCH_INSTANCE_ID, @InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE, NULL AS EXECUTION_STATUS_CODE, 0 AS REPORTED_COUNT, 0 AS FAILED_COUNT, 0 AS FAILED_BATCH_COUNT;
  RETURN;
END;

EXEC [omd].[EndBatchModuleInstances]
   @BatchInstanceId      = @Id
  ,@ModuleResults        = @Results
  ,@BatchEventCode       = @EventCode
  ,@IncludeChildBatches  = 'Y'
  ,@ReportedCount        = @ReportedCount OUTPUT
  ,@FailedCount          = @FailedCount OUTPUT
  ,@FailedBatchCount     = @FailedBatchCount OUTPUT
  ,@ExecutionStatusCode  = @ExecutionStatusCode OUTPUT
  ,@SuccessIndicator     = @SuccessIndicator OUTPUT
  ,@MessageLog           = @MessageLog OUTPUT;

SELECT @Id AS BATCH_INSTANCE_ID, @InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE, @ExecutionStatusCode AS EXECUTION_STATUS_CODE, @ReportedCount AS REPORTED_COUNT, @FailedCount AS FAILED_COUNT, @FailedBatchCount AS FAILED_BATCH_COUNT;

IF @SuccessIndicator <> 'Y'
BEGIN
  SET @ErrorMessage = LEFT(N'DIRECT could not close Batch Instance ' + CONVERT(NVARCHAR(20), @Id) + N': ' + COALESCE(@MessageLog, N''), 2048);
  THROW 50000, @ErrorMessage, 1;
END;

IF UPPER(COALESCE(@RaiseError, N'Y')) = N'Y' AND (@FailedCount > 0 OR @FailedBatchCount > 0 OR @ExecutionStatusCode <> N'Succeeded')
BEGIN
  SET @ErrorMessage = N'Batch Instance ' + CONVERT(NVARCHAR(20), @Id) + N' ended as ' + COALESCE(@ExecutionStatusCode, N'unknown') + N' with '
    + CONVERT(NVARCHAR(10), @FailedCount) + N' failed Module Instance(s) and ' + CONVERT(NVARCHAR(10), @FailedBatchCount) + N' failed child Batch Instance(s). See omd_reporting.vw_MODULE_FAILURES and omd_reporting.vw_EXECUTION_LOG_BATCH_INSTANCE.';
  THROW 50000, @ErrorMessage, 1;
END;

-- DIRECT Run Batch, activity 'Fail Batch' (repository database). Runs when 'Run Modules' itself failed.
-- Fails all open Module Instances of the Batch Instance and its child Batch Instances, closes them as Failure, logs the error, then fails when @RaiseError = 'Y'.
-- Parameters: @BatchInstanceId (string), @InternalProcessingStatusCode, @ErrorMessage (string), @RaiseError (string, 'Y' or 'N').
SET NOCOUNT ON;

DECLARE @Id BIGINT = TRY_CONVERT(BIGINT, NULLIF(TRIM(@BatchInstanceId), N''));
DECLARE @Detail NVARCHAR(4000) = LEFT(N'The orchestrator failed to run the Modules of the Batch: ' + COALESCE(@ErrorMessage, N'no error message'), 4000);
DECLARE @Message NVARCHAR(2048) = LEFT(@Detail, 2048);

IF @Id IS NOT NULL AND @InternalProcessingStatusCode = N'Proceed'
BEGIN
  EXEC [omd].[InsertIntoEventLog] @ModuleInstanceId = 0, @BatchInstanceId = @Id, @EventDetail = @Detail;
  EXEC [omd].[EndBatchModuleInstances] @BatchInstanceId = @Id, @ModuleResults = NULL, @BatchEventCode = N'Failure', @IncludeChildBatches = 'Y';
END;

IF UPPER(COALESCE(@RaiseError, N'Y')) = N'Y' THROW 50000, @Message, 1;

SELECT @Id AS INSTANCE_ID, N'Failure' AS EVENT_CODE;
